mapper.update:
update workshop_version set review_state='PENDING',audit_task_id=#{auditTaskId},
  review_hash=#{reviewHash},review_snapshot=#{reviewSnapshot}
where version_id=#{versionId} and seller_id=#{owner} and review_state='DRAFT' and source_kind='PRIVATE_TEMPLATE'
  and content_hash=#{contentHash} and terms_hash=#{termsHash} and price_fen=#{priceFen}
